interface UseCopyToClipboardResult {
  copy: (text: string) => Promise<boolean>;
  copiedText: string | null;
  isCopied: boolean;
}

function useCopyToClipboard(resetDelay: number = 2000): UseCopyToClipboardResult {
  const [copiedText, setCopiedText] = useState<string | null>(null);
  const [isCopied, setIsCopied] = useState(false);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, []);

  const legacyCopy = (text: string): boolean => {
    const textarea = document.createElement('textarea');
    textarea.value = text;
    textarea.style.position = 'fixed';
    textarea.style.opacity = '0';
    document.body.appendChild(textarea);
    textarea.focus();
    textarea.select();
    let succeeded = false;
    try {
      succeeded = document.execCommand('copy');
    } catch {
      succeeded = false;
    } finally {
      document.body.removeChild(textarea);
    }
    return succeeded;
  };

  const copy = useCallback(
    async (text: string): Promise<boolean> => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
        timeoutRef.current = null;
      }

      let succeeded = false;

      if (navigator.clipboard && navigator.clipboard.writeText) {
        try {
          await navigator.clipboard.writeText(text);
          succeeded = true;
        } catch {
          succeeded = legacyCopy(text);
        }
      } else {
        succeeded = legacyCopy(text);
      }

      if (succeeded) {
        setCopiedText(text);
        setIsCopied(true);
        timeoutRef.current = setTimeout(() => {
          setIsCopied(false);
          timeoutRef.current = null;
        }, resetDelay);
      }

      return succeeded;
    },
    [resetDelay]
  );

  return { copy, copiedText, isCopied };
}

description.en:
Implement a flexible form builder component that supports:

1. **Dynamic field registration** — add and remove fields at runtime
2. **Custom validation rules** — support built-in rules (required, email, minLength, maxLength, pattern, custom) and chainable validators
3. **Field-level and form-level errors** — display errors next to fields and at form level
4. **Touched/Dirty state tracking** — show errors only for fields the user has already interacted with
5. **Form state management** — track values, errors, touched state, dirty state
6. **Submit handling** — prevent submission if invalid, pass validated data

**Example Usage:**

```tsx
const form = useForm({
  initialValues: { email: '', password: '', age: '' },
  onSubmit: (values) => console.log(values)
});

form.registerField('email', [
  { type: 'required', message: 'Email is required' },
  { type: 'email', message: 'Invalid email' }
]);

form.registerField('password', [
  { type: 'required' },
  { type: 'minLength', value: 8, message: 'At least 8 characters' }
]);

form.registerField('age', [
  { type: 'custom', validator: (val) => val > 0 && val < 150, message: 'Invalid age' }
]);

// Returns { isValid: boolean, errors: {}, values: {} }
const result = form.validate();
```

**Edge cases:**

- Async validation support
- Cross-field validation
- Array fields (dynamic arrays)
- Conditional field visibility affecting validation

